using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// The synthesiser. Runs entirely on the audio thread, entirely from code: there are no audio
/// files in this project, and there deliberately are none, because the point of the piece is that
/// the sound is generated by the same state that grows the pattern rather than selected from a
/// library of takes.
///
/// Put this on a GameObject that also has an AudioSource (it can have no clip, but it must be
/// playing, and Spatial Blend should be 2D). Unity then calls OnAudioFilterRead on it.
///
/// Thread discipline: the composer pushes RDNoteEvent structs into a locked queue from Update;
/// nothing here touches the Unity API beyond Mathf, and randomness comes from System.Random
/// because UnityEngine.Random is main-thread only.
/// </summary>
[RequireComponent(typeof(AudioSource))]
public class RDAudioEngine : MonoBehaviour
{
    [Header("Mix")]
    [Range(0f, 1f)] [SerializeField] private float masterGain = 0.55f;

    [Tooltip("Soft clip ceiling. Keeps a dense passage from distorting on gallery speakers.")]
    [Range(0.1f, 1f)] [SerializeField] private float limiterCeiling = 0.92f;

    [Header("Room")]
    [Tooltip("Reverb send. Temple acoustics want this high; a small gallery wants it lower.")]
    [Range(0f, 1f)] [SerializeField] private float reverbMix = 0.42f;

    [Range(0f, 0.99f)] [SerializeField] private float reverbFeedback = 0.82f;

    [Tooltip("Damping of the reverb tail. Higher swallows the bright partials first, like stone.")]
    [Range(0f, 0.95f)] [SerializeField] private float reverbDamping = 0.35f;

    [Header("Polyphony")]
    [SerializeField] private int templeBellVoices = 5;
    [SerializeField] private int rinVoices = 4;
    [SerializeField] private int kendangVoices = 8;
    [SerializeField] private int gongVoices = 3;
    [SerializeField] private int pipaVoices = 8;
    [SerializeField] private int glitchVoices = 6;
    [SerializeField] private int signalToneVoices = 5;

    [Header("Read-only")]
    [SerializeField] private int debugActiveVoices;
    [SerializeField] private int debugDroppedNotes;

    private const int MaxQueuedNotes = 128;

    private readonly Queue<RDNoteEvent> pending = new Queue<RDNoteEvent>(MaxQueuedNotes);
    private readonly object queueLock = new object();

    // Preallocated: the audio thread must not allocate.
    private readonly RDNoteEvent[] drainBuffer = new RDNoteEvent[MaxQueuedNotes];

    private RDVoice[] bellPool;
    private RDVoice[] rinPool;
    private RDVoice[] kendangPool;
    private RDVoice[] gongPool;
    private RDVoice[] pipaPool;
    private RDVoice[] glitchPool;
    private RDVoice[] signalTonePool;
    private RDVoice[] allVoices;

    private RDSignalBed signalBed;
    private RDReverb reverb;
    private System.Random rng;

    private float sampleRate = 48000f;
    private bool ready;

    private void Awake()
    {
        // AudioSettings must be read on the main thread.
        sampleRate = AudioSettings.outputSampleRate;
        if (sampleRate < 8000f) sampleRate = 48000f;

        rng = new System.Random(20261026);

        bellPool = BuildPool(templeBellVoices, () => new RDBellVoice(RDBellVoice.BonshoRatios, RDBellVoice.BonshoAmps, RDBellVoice.BonshoDecays));
        rinPool = BuildPool(rinVoices, () => new RDBellVoice(RDBellVoice.RinRatios, RDBellVoice.RinAmps, RDBellVoice.RinDecays));
        kendangPool = BuildPool(kendangVoices, () => new RDKendangVoice(rng));
        gongPool = BuildPool(gongVoices, () => new RDGongVoice());
        pipaPool = BuildPool(pipaVoices, () => new RDPipaVoice(rng));
        glitchPool = BuildPool(glitchVoices, () => new RDGlitchVoice());
        signalTonePool = BuildPool(signalToneVoices, () => new RDSignalToneVoice());

        var all = new List<RDVoice>();
        all.AddRange(bellPool);
        all.AddRange(rinPool);
        all.AddRange(kendangPool);
        all.AddRange(gongPool);
        all.AddRange(pipaPool);
        all.AddRange(glitchPool);
        all.AddRange(signalTonePool);
        allVoices = all.ToArray();

        for (int i = 0; i < allVoices.Length; i++)
            allVoices[i].SetSampleRate(sampleRate);

        signalBed = new RDSignalBed(sampleRate);
        reverb = new RDReverb(sampleRate);

        ready = true;
    }

    private RDVoice[] BuildPool(int count, System.Func<RDVoice> factory)
    {
        count = Mathf.Max(1, count);
        RDVoice[] pool = new RDVoice[count];

        for (int i = 0; i < count; i++)
            pool[i] = factory();

        return pool;
    }

    /// <summary>Queue a note. Safe to call from Update. Never blocks the audio thread for long.</summary>
    public void Play(RDNoteEvent note)
    {
        if (!ready) return;

        lock (queueLock)
        {
            if (pending.Count >= MaxQueuedNotes)
            {
                debugDroppedNotes++;
                return;
            }

            pending.Enqueue(note);
        }
    }

    /// <summary>
    /// Set the level of the dead-channel bed. 0 silences it; 1 is a fully lost signal. Unrest
    /// raises the dropout rate, the crackle density and the carrier drift. Safe from Update; the
    /// bed crossfades over about a second rather than switching.
    /// </summary>
    public void SetSignalNoise(float level, float unrest)
    {
        if (!ready || signalBed == null) return;
        signalBed.SetLevel(level, unrest);
    }

    /// <summary>
    /// A slow swell in the machine room, -1 to 1, driven from the same phase as the surface's
    /// breathing so the sound and the picture rise and fall together. Driving both from one
    /// clock is the whole point: two breaths at the same rate but not the same phase read as
    /// two things, and the room has to read as one.
    /// </summary>
    public void SetRoomBreath(float breath)
    {
        if (!ready || signalBed == null) return;
        signalBed.SetBreath(breath);
    }

    /// <summary>
    /// Rate of the monitor in the empty room, in beats per minute. Drop it and the room is
    /// settling; the beep and the surface's pump both follow, because they are one clock.
    /// </summary>
    public void SetPulseRate(float beatsPerMinute)
    {
        if (!ready || signalBed == null) return;
        signalBed.SetPulse(beatsPerMinute);
    }

    /// <summary>
    /// The cardiac envelope the beep is currently on, 0 to 1. The surface pumps on this rather
    /// than on an oscillator of its own: two clocks at the same rate drift, and a picture that
    /// swells a third of a beat after the sound reads as two machines in one room.
    /// </summary>
    public float PulseEnvelope => ready && signalBed != null ? signalBed.PulseEnvelope : 0f;

    /// <summary>
    /// The shape of one beat, from seconds since it fired. Public and static so the surface can
    /// run the same curve on a local clock in a scene with no audio engine in it.
    ///
    /// Measured in seconds, not in fractions of a cycle, and that is the whole character: as the
    /// rate slows the beat keeps its shape and the SILENCE between beats grows. Stretching the
    /// pulse instead would read as a tape slowing down rather than as a body at rest.
    /// </summary>
    public static float CardiacEnvelope(float secondsSinceBeat)
    {
        // Systole, then the small second bump about a third of a second later. That second bump
        // is doing most of the work: one hump a second is a metronome, two is a heart.
        float systole = BeatShape(secondsSinceBeat, 0.045f, 0.18f);
        float dicrotic = BeatShape(secondsSinceBeat - 0.32f, 0.030f, 0.10f) * 0.3f;

        return Mathf.Clamp01(systole + dicrotic);
    }

    private static float BeatShape(float t, float attack, float decay)
    {
        if (t < 0f) return 0f;
        if (t < attack) return t / attack;

        return Mathf.Exp(-(t - attack) / decay);
    }

    private void Update()
    {
        // Mirrored to the inspector for the operator overlay; reading an int is atomic enough.
        int active = 0;
        if (allVoices != null)
        {
            for (int i = 0; i < allVoices.Length; i++)
                if (allVoices[i].Active) active++;
        }

        debugActiveVoices = active;

        if (reverb != null)
            reverb.SetParameters(reverbFeedback, reverbDamping);
    }

    private void OnAudioFilterRead(float[] data, int channels)
    {
        if (!ready || allVoices == null) return;

        DrainQueue();

        int frames = data.Length / channels;
        float wet = reverbMix;
        float dry = 1f - reverbMix * 0.5f;

        for (int f = 0; f < frames; f++)
        {
            float left = 0f;
            float right = 0f;

            for (int v = 0; v < allVoices.Length; v++)
            {
                RDVoice voice = allVoices[v];
                if (!voice.Active) continue;

                voice.Render(out float vl, out float vr);
                left += vl;
                right += vr;
            }

            reverb.Process(left, right, out float rl, out float rr);

            // The dead channel is added after the reverb, deliberately dry: the instruments are
            // in the room, the static is in your ears.
            signalBed.Render(out float sl, out float sr);

            float outL = SoftClip((left * dry + rl * wet + sl) * masterGain) * limiterCeiling;
            float outR = SoftClip((right * dry + rr * wet + sr) * masterGain) * limiterCeiling;

            int baseIndex = f * channels;

            if (channels == 1)
            {
                data[baseIndex] = (outL + outR) * 0.5f;
            }
            else
            {
                data[baseIndex] = outL;
                data[baseIndex + 1] = outR;

                for (int c = 2; c < channels; c++)
                    data[baseIndex + c] = 0f;
            }
        }
    }

    private void DrainQueue()
    {
        // Copy under the lock, start voices outside it. Triggering inside would keep the audio
        // thread holding a lock that Play() wants from the main thread - a priority inversion
        // that shows up as an occasional click rather than as anything diagnosable.
        int count = 0;

        lock (queueLock)
        {
            while (pending.Count > 0 && count < drainBuffer.Length)
                drainBuffer[count++] = pending.Dequeue();
        }

        for (int i = 0; i < count; i++)
        {
            RDVoice voice = ClaimVoice(drainBuffer[i].kind);
            if (voice != null) voice.Trigger(drainBuffer[i]);
        }
    }

    /// <summary>
    /// Takes a free voice from the right pool, or steals the quietest one so a dense passage
    /// thins out rather than dropping the newest, most relevant note.
    /// </summary>
    private RDVoice ClaimVoice(RDVoiceKind kind)
    {
        RDVoice[] pool = PoolFor(kind);
        if (pool == null || pool.Length == 0) return null;

        for (int i = 0; i < pool.Length; i++)
            if (!pool[i].Active) return pool[i];

        int quietest = 0;
        float lowest = float.MaxValue;

        for (int i = 0; i < pool.Length; i++)
        {
            float level = pool[i].CurrentLevel;
            if (level < lowest)
            {
                lowest = level;
                quietest = i;
            }
        }

        return pool[quietest];
    }

    private RDVoice[] PoolFor(RDVoiceKind kind)
    {
        switch (kind)
        {
            case RDVoiceKind.TempleBell: return bellPool;
            case RDVoiceKind.Rin: return rinPool;
            case RDVoiceKind.Kendang: return kendangPool;
            case RDVoiceKind.Gong: return gongPool;
            case RDVoiceKind.Pipa: return pipaPool;
            case RDVoiceKind.Glitch: return glitchPool;
            case RDVoiceKind.Signal: return signalTonePool;
            default: return null;
        }
    }

    private static float SoftClip(float x)
    {
        // tanh-ish curve, cheap and monotonic.
        if (x > 3f) return 1f;
        if (x < -3f) return -1f;

        float x2 = x * x;
        return x * (27f + x2) / (27f + 9f * x2);
    }

    private void OnValidate()
    {
        limiterCeiling = Mathf.Clamp(limiterCeiling, 0.1f, 1f);
        masterGain = Mathf.Clamp01(masterGain);
    }
}

// ===========================================================================================
//  Voices
// ===========================================================================================

internal abstract class RDVoice
{
    public bool Active { get; protected set; }

    /// <summary>Current envelope level, used for voice stealing.</summary>
    public abstract float CurrentLevel { get; }

    protected float sampleRate = 48000f;
    protected float panL = 0.707f;
    protected float panR = 0.707f;

    public void SetSampleRate(float rate) => sampleRate = Mathf.Max(8000f, rate);

    public abstract void Trigger(RDNoteEvent note);
    public abstract void Render(out float left, out float right);

    protected void SetPan(float pan)
    {
        float p = Mathf.Clamp(pan, -1f, 1f);
        float angle = (p + 1f) * 0.25f * Mathf.PI; // 0 .. pi/2
        panL = Mathf.Cos(angle);
        panR = Mathf.Sin(angle);
    }

    /// <summary>Per-sample multiplier that decays to about -60 dB in the given time.</summary>
    protected float DecayCoefficient(float seconds)
    {
        float t = Mathf.Max(0.005f, seconds);
        return Mathf.Exp(-6.9078f / (t * sampleRate));
    }

    protected const float TwoPi = 6.28318530718f;
}

/// <summary>
/// Additive inharmonic bell. Bronze bells have no harmonic series: their partials sit at
/// stretched, uneven ratios, which is why a struck bell reads as a pitch plus a cloud rather
/// than a note. Two slightly detuned copies of the lowest partial produce the slow throb that
/// Japanese bell makers call uchi-hibiki.
/// </summary>
internal sealed class RDBellVoice : RDVoice
{
    // Bonsho, the big suspended temple bell. Ratios relative to the hum tone.
    public static readonly float[] BonshoRatios = { 1.00f, 2.00f, 2.41f, 3.02f, 3.61f, 4.38f, 5.27f, 6.31f };
    public static readonly float[] BonshoAmps = { 1.00f, 0.62f, 0.44f, 0.31f, 0.22f, 0.16f, 0.11f, 0.07f };
    public static readonly float[] BonshoDecays = { 1.00f, 0.74f, 0.55f, 0.40f, 0.28f, 0.20f, 0.14f, 0.09f };

    // Rin, the small bowl bell on a cushion. Far fewer partials, much longer ring.
    public static readonly float[] RinRatios = { 1.00f, 2.74f, 5.41f, 8.93f };
    public static readonly float[] RinAmps = { 1.00f, 0.42f, 0.18f, 0.07f };
    public static readonly float[] RinDecays = { 1.00f, 0.78f, 0.52f, 0.30f };

    private const int MaxPartials = 8;

    private readonly float[] ratios;
    private readonly float[] baseAmps;
    private readonly float[] decayScales;

    private readonly float[] phase = new float[MaxPartials];
    private readonly float[] increment = new float[MaxPartials];
    private readonly float[] amplitude = new float[MaxPartials];
    private readonly float[] decayCoef = new float[MaxPartials];

    private int partialCount;

    private float beatPhase;
    private float beatIncrement;
    private float beatDepth;

    private float level;

    public RDBellVoice(float[] ratios, float[] amps, float[] decays)
    {
        this.ratios = ratios;
        baseAmps = amps;
        decayScales = decays;
    }

    public override float CurrentLevel => level;

    public override void Trigger(RDNoteEvent note)
    {
        SetPan(note.pan);

        partialCount = Mathf.Min(MaxPartials, ratios.Length);

        // Brightness decides how much of the upper cloud the mallet excites: a padded beam on a
        // temple bell brings out the hum, a hard strike brings out the ring.
        float bright = Mathf.Clamp01(note.brightness);
        float amp = Mathf.Clamp(note.amplitude, 0f, 1f);

        for (int i = 0; i < partialCount; i++)
        {
            float f = note.frequency * ratios[i];

            // Fold anything above Nyquist back down instead of aliasing.
            if (f > sampleRate * 0.45f)
            {
                amplitude[i] = 0f;
                increment[i] = 0f;
                decayCoef[i] = 0.5f;
                continue;
            }

            float tilt = Mathf.Lerp(Mathf.Pow(0.45f, i), 1f, bright);

            phase[i] = 0f;
            increment[i] = TwoPi * f / sampleRate;
            amplitude[i] = baseAmps[i] * tilt * amp;
            decayCoef[i] = DecayCoefficient(note.decay * decayScales[i]);
        }

        // Beating rate scales with pitch: bigger bells throb slower.
        beatPhase = 0f;
        beatIncrement = TwoPi * Mathf.Lerp(0.6f, 2.8f, Mathf.InverseLerp(40f, 600f, note.frequency)) / sampleRate;
        beatDepth = Mathf.Lerp(0.10f, 0.28f, 1f - bright);

        level = amp;
        Active = true;
    }

    public override void Render(out float left, out float right)
    {
        float sum = 0f;
        float loudest = 0f;

        for (int i = 0; i < partialCount; i++)
        {
            if (amplitude[i] <= 0.00002f) continue;

            sum += Mathf.Sin(phase[i]) * amplitude[i];

            phase[i] += increment[i];
            if (phase[i] > TwoPi) phase[i] -= TwoPi;

            amplitude[i] *= decayCoef[i];

            if (amplitude[i] > loudest) loudest = amplitude[i];
        }

        beatPhase += beatIncrement;
        if (beatPhase > TwoPi) beatPhase -= TwoPi;

        sum *= 1f + beatDepth * Mathf.Sin(beatPhase);

        level = loudest;

        if (loudest <= 0.00002f)
        {
            Active = false;
            left = 0f;
            right = 0f;
            return;
        }

        // 0.34 keeps eight summed partials inside headroom.
        sum *= 0.34f;

        left = sum * panL;
        right = sum * panR;
    }
}

/// <summary>
/// Kendang, the Indonesian hand drum that drives gamelan tempo. A struck membrane is a noise
/// burst plus a set of Bessel modes, which are inharmonic and closely spaced; the hand position
/// changes how much noise and how much tone you get, which is what brightness controls here.
/// </summary>
internal sealed class RDKendangVoice : RDVoice
{
    // Ratios of the first circular-membrane modes.
    private static readonly float[] ModeRatios = { 1.00f, 1.593f, 2.135f, 2.295f, 2.917f };
    private static readonly float[] ModeAmps = { 1.00f, 0.58f, 0.36f, 0.30f, 0.18f };

    private readonly System.Random rng;

    private readonly float[] phase = new float[5];
    private readonly float[] increment = new float[5];
    private readonly float[] amplitude = new float[5];
    private readonly float[] decayCoef = new float[5];

    private float noiseAmp;
    private float noiseDecay;
    private float noiseLp;
    private float noiseCutoff;

    private float level;

    public RDKendangVoice(System.Random random) => rng = random;

    public override float CurrentLevel => level;

    public override void Trigger(RDNoteEvent note)
    {
        SetPan(note.pan);

        float bright = Mathf.Clamp01(note.brightness);
        float amp = Mathf.Clamp(note.amplitude, 0f, 1f);

        for (int i = 0; i < ModeRatios.Length; i++)
        {
            float f = note.frequency * ModeRatios[i];

            if (f > sampleRate * 0.45f)
            {
                amplitude[i] = 0f;
                increment[i] = 0f;
                decayCoef[i] = 0.5f;
                continue;
            }

            phase[i] = 0f;
            increment[i] = TwoPi * f / sampleRate;
            amplitude[i] = ModeAmps[i] * amp * Mathf.Lerp(1f, 0.55f, bright);

            // Higher modes die fast, which is what makes a drum a hit and not a chord.
            float modeDecay = note.decay * Mathf.Pow(0.62f, i);
            decayCoef[i] = DecayCoefficient(modeDecay);
        }

        // The slap. Bright hits are almost all this.
        noiseAmp = amp * Mathf.Lerp(0.25f, 1.1f, bright);
        noiseDecay = DecayCoefficient(note.decay * Mathf.Lerp(0.20f, 0.09f, bright));
        noiseCutoff = Mathf.Lerp(0.06f, 0.55f, bright);
        noiseLp = 0f;

        level = amp;
        Active = true;
    }

    public override void Render(out float left, out float right)
    {
        float sum = 0f;
        float loudest = 0f;

        for (int i = 0; i < ModeRatios.Length; i++)
        {
            if (amplitude[i] <= 0.00002f) continue;

            sum += Mathf.Sin(phase[i]) * amplitude[i];

            phase[i] += increment[i];
            if (phase[i] > TwoPi) phase[i] -= TwoPi;

            amplitude[i] *= decayCoef[i];

            if (amplitude[i] > loudest) loudest = amplitude[i];
        }

        if (noiseAmp > 0.00002f)
        {
            float white = (float)(rng.NextDouble() * 2.0 - 1.0);
            noiseLp += (white - noiseLp) * noiseCutoff;

            sum += noiseLp * noiseAmp;
            noiseAmp *= noiseDecay;

            if (noiseAmp > loudest) loudest = noiseAmp;
        }

        level = loudest;

        if (loudest <= 0.00002f)
        {
            Active = false;
            left = 0f;
            right = 0f;
            return;
        }

        sum *= 0.45f;

        left = sum * panL;
        right = sum * panR;
    }
}

/// <summary>
/// The low bronze gong that marks the end of a gamelan cycle. Unlike the bell it blooms: the
/// energy takes a moment to spread into the upper partials, and the fundamental sags slightly
/// as the plate flexes. Both of those are modelled here, because without them a gong is just a
/// quiet bell.
/// </summary>
internal sealed class RDGongVoice : RDVoice
{
    private static readonly float[] Ratios = { 1.00f, 1.48f, 2.16f, 2.93f, 3.71f, 4.62f };
    private static readonly float[] Amps = { 1.00f, 0.55f, 0.40f, 0.28f, 0.18f, 0.12f };

    private const int Partials = 6;

    private readonly float[] phase = new float[Partials];
    private readonly float[] increment = new float[Partials];
    private readonly float[] target = new float[Partials];
    private readonly float[] amplitude = new float[Partials];
    private readonly float[] decayCoef = new float[Partials];
    private readonly float[] bloomRate = new float[Partials];

    private float bendSemitones;
    private float bendRemaining;
    private float bendCoef;
    private float baseFrequency;

    private float beatPhase;
    private float beatIncrement;

    private float level;

    public override float CurrentLevel => level;

    public override void Trigger(RDNoteEvent note)
    {
        SetPan(note.pan);

        float bright = Mathf.Clamp01(note.brightness);
        float amp = Mathf.Clamp(note.amplitude, 0f, 1f);

        baseFrequency = note.frequency;

        for (int i = 0; i < Partials; i++)
        {
            float f = note.frequency * Ratios[i];

            if (f > sampleRate * 0.45f)
            {
                amplitude[i] = 0f;
                target[i] = 0f;
                increment[i] = 0f;
                decayCoef[i] = 0.5f;
                bloomRate[i] = 1f;
                continue;
            }

            phase[i] = 0f;
            increment[i] = TwoPi * f / sampleRate;

            target[i] = Amps[i] * amp * Mathf.Lerp(0.6f, 1f, bright);

            // Partial 0 speaks immediately; the upper plate modes take up to a second to fill in.
            amplitude[i] = i == 0 ? target[i] : 0f;
            bloomRate[i] = 1f - Mathf.Exp(-1f / (Mathf.Lerp(0.05f, 0.9f, i / (float)Partials) * sampleRate));

            decayCoef[i] = DecayCoefficient(note.decay * Mathf.Pow(0.80f, i));
        }

        // Gongs bend down, not up.
        bendSemitones = -Mathf.Abs(note.bend);
        bendRemaining = bendSemitones;
        bendCoef = Mathf.Exp(-1f / (0.7f * sampleRate));

        beatPhase = 0f;
        beatIncrement = TwoPi * 0.35f / sampleRate;

        level = amp;
        Active = true;
    }

    public override void Render(out float left, out float right)
    {
        float sum = 0f;
        float loudest = 0f;

        // One shared pitch offset, applied to every partial, so the whole gong sags together.
        bendRemaining *= bendCoef;
        float bendFactor = Mathf.Pow(2f, (bendSemitones - bendRemaining) / 12f);

        for (int i = 0; i < Partials; i++)
        {
            if (target[i] <= 0f && amplitude[i] <= 0.00002f) continue;

            sum += Mathf.Sin(phase[i]) * amplitude[i];

            phase[i] += increment[i] * bendFactor;
            if (phase[i] > TwoPi) phase[i] -= TwoPi;

            // Bloom toward the target, then decay with it.
            amplitude[i] += (target[i] - amplitude[i]) * bloomRate[i];
            target[i] *= decayCoef[i];

            if (amplitude[i] > loudest) loudest = amplitude[i];
        }

        beatPhase += beatIncrement;
        if (beatPhase > TwoPi) beatPhase -= TwoPi;

        sum *= 1f + 0.18f * Mathf.Sin(beatPhase);

        level = loudest;

        if (loudest <= 0.00002f)
        {
            Active = false;
            left = 0f;
            right = 0f;
            return;
        }

        sum *= 0.32f;

        left = sum * panL;
        right = sum * panR;
    }
}

/// <summary>
/// Pipa. Additive rather than a delay line, because the instrument's vocabulary is built on
/// slides and on the rolling tremolo (lunzhi), and both need pitch and amplitude to be freely
/// controllable per sample. A short filtered noise burst stands in for the plectrum.
/// </summary>
internal sealed class RDPipaVoice : RDVoice
{
    private const int Harmonics = 14;

    private readonly System.Random rng;

    private readonly float[] phase = new float[Harmonics];
    private readonly float[] amplitude = new float[Harmonics];
    private readonly float[] decayCoef = new float[Harmonics];

    private float frequency;
    private float bendSemitones;
    private float bendRemaining;
    private float bendCoef;

    private float tremoloPhase;
    private float tremoloIncrement;
    private float tremoloDepth;

    private float pluckAmp;
    private float pluckDecay;
    private float pluckLp;

    private float level;

    public RDPipaVoice(System.Random random) => rng = random;

    public override float CurrentLevel => level;

    public override void Trigger(RDNoteEvent note)
    {
        SetPan(note.pan);

        float bright = Mathf.Clamp01(note.brightness);
        float amp = Mathf.Clamp(note.amplitude, 0f, 1f);

        frequency = note.frequency;

        for (int i = 0; i < Harmonics; i++)
        {
            float f = frequency * (i + 1);

            if (f > sampleRate * 0.45f)
            {
                amplitude[i] = 0f;
                decayCoef[i] = 0.5f;
                continue;
            }

            // A wire string on a hard soundboard: slow rolloff, so it stays metallic.
            float rolloff = 1f / Mathf.Pow(i + 1, Mathf.Lerp(1.6f, 0.95f, bright));

            phase[i] = (float)(rng.NextDouble() * TwoPi);
            amplitude[i] = rolloff * amp;
            decayCoef[i] = DecayCoefficient(note.decay * Mathf.Pow(0.87f, i));
        }

        bendSemitones = note.bend;
        bendRemaining = bendSemitones;
        bendCoef = Mathf.Exp(-1f / (0.18f * sampleRate));

        tremoloDepth = Mathf.Clamp01(note.tremolo);
        tremoloPhase = 0f;
        tremoloIncrement = TwoPi * Mathf.Lerp(6.5f, 13.5f, tremoloDepth) / sampleRate;

        pluckAmp = amp * Mathf.Lerp(0.12f, 0.40f, bright);
        pluckDecay = DecayCoefficient(0.012f);
        pluckLp = 0f;

        level = amp;
        Active = true;
    }

    public override void Render(out float left, out float right)
    {
        bendRemaining *= bendCoef;
        float bendFactor = Mathf.Pow(2f, (bendSemitones - bendRemaining) / 12f);
        float baseIncrement = TwoPi * frequency * bendFactor / sampleRate;

        float sum = 0f;
        float loudest = 0f;

        for (int i = 0; i < Harmonics; i++)
        {
            if (amplitude[i] <= 0.00002f) continue;

            sum += Mathf.Sin(phase[i]) * amplitude[i];

            phase[i] += baseIncrement * (i + 1);
            while (phase[i] > TwoPi) phase[i] -= TwoPi;

            amplitude[i] *= decayCoef[i];

            if (amplitude[i] > loudest) loudest = amplitude[i];
        }

        if (tremoloDepth > 0.001f)
        {
            tremoloPhase += tremoloIncrement;
            if (tremoloPhase > TwoPi) tremoloPhase -= TwoPi;

            sum *= 1f - tremoloDepth * 0.5f * (1f - Mathf.Cos(tremoloPhase));
        }

        if (pluckAmp > 0.00002f)
        {
            float white = (float)(rng.NextDouble() * 2.0 - 1.0);
            pluckLp += (white - pluckLp) * 0.7f;

            sum += pluckLp * pluckAmp;
            pluckAmp *= pluckDecay;

            if (pluckAmp > loudest) loudest = pluckAmp;
        }

        level = loudest;

        if (loudest <= 0.00002f)
        {
            Active = false;
            left = 0f;
            right = 0f;
            return;
        }

        sum *= 0.30f;

        left = sum * panL;
        right = sum * panR;
    }
}

/// <summary>
/// Electronic artefact. Not an instrument and not trying to be one: a decimated square with a
/// hard envelope, a stutter gate and amplitude quantisation. These punctuate the empty room,
/// where the piece has nobody to transmit to.
/// </summary>
internal sealed class RDGlitchVoice : RDVoice
{
    private float phase;
    private float increment;
    private float pulseWidth;

    private float amp;
    private float decayCoef;

    private float stutterPhase;
    private float stutterIncrement;

    private float holdValue;
    private float holdCounter;
    private float holdPeriod;

    private float crushLevels;

    private float bendSemitones;
    private float bendStepped;
    private float bendStepCounter;
    private float bendStepPeriod;

    public override float CurrentLevel => amp;

    public override void Trigger(RDNoteEvent note)
    {
        SetPan(note.pan);

        float bright = Mathf.Clamp01(note.brightness);

        increment = TwoPi * Mathf.Max(20f, note.frequency) / sampleRate;
        phase = 0f;
        pulseWidth = Mathf.Lerp(0.5f, 0.12f, bright);

        amp = Mathf.Clamp(note.amplitude, 0f, 1f);
        decayCoef = DecayCoefficient(Mathf.Max(0.01f, note.decay));

        // A hard on/off gate rather than a tremolo: the artefact being imitated is a buffer
        // repeating, not a string being shaken.
        stutterIncrement = TwoPi * Mathf.Lerp(0f, 38f, Mathf.Clamp01(note.tremolo)) / sampleRate;
        stutterPhase = 0f;

        // Sample and hold below the output rate. This is what makes it sound like a sample rate
        // rather than like a waveform.
        float decimateHz = Mathf.Lerp(2200f, 19000f, bright);
        holdPeriod = Mathf.Max(1f, sampleRate / decimateHz);
        holdCounter = 0f;
        holdValue = 0f;

        crushLevels = Mathf.Lerp(24f, 3f, Mathf.Clamp01(note.harmonic));

        // The pitch moves in stairs, not in a glide.
        bendSemitones = note.bend;
        bendStepped = 0f;
        bendStepPeriod = Mathf.Max(1f, sampleRate * 0.035f);
        bendStepCounter = 0f;

        Active = true;
    }

    public override void Render(out float left, out float right)
    {
        bendStepCounter += 1f;
        if (bendStepCounter >= bendStepPeriod)
        {
            bendStepCounter -= bendStepPeriod;
            bendStepped += bendSemitones * 0.18f;

            if (Mathf.Abs(bendStepped) > Mathf.Abs(bendSemitones))
                bendStepped = bendSemitones;
        }

        phase += increment * Mathf.Pow(2f, bendStepped / 12f);
        while (phase > TwoPi) phase -= TwoPi;

        float square = (phase / TwoPi) < pulseWidth ? 1f : -1f;

        holdCounter += 1f;
        if (holdCounter >= holdPeriod)
        {
            holdCounter -= holdPeriod;
            holdValue = square;
        }

        float value = holdValue;

        if (crushLevels > 1f)
            value = Mathf.Round(value * crushLevels) / crushLevels;

        if (stutterIncrement > 0f)
        {
            stutterPhase += stutterIncrement;
            if (stutterPhase > TwoPi) stutterPhase -= TwoPi;

            if (Mathf.Sin(stutterPhase) < 0f) value = 0f;
        }

        value *= amp;
        amp *= decayCoef;

        if (amp <= 0.0002f)
        {
            Active = false;
            left = 0f;
            right = 0f;
            return;
        }

        value *= 0.22f;

        left = value * panL;
        right = value * panR;
    }
}

// ===========================================================================================
//  The empty room
// ===========================================================================================

/// <summary>
/// A machine signalling. Short, clean, deliberate tones - telemetry, a handshake, a scan - of the
/// kind equipment makes when it is talking to other equipment and not to anyone.
///
/// This replaced a vocal call, and the difference is the point: a voice calling across an empty
/// room makes the room lonely, which says the piece misses you. Signal tones say the opposite -
/// the machines carry on addressing each other, and your absence has not been noticed. That is
/// colder and it is the truer reading.
///
/// It is also NOT the glitch voice. Nothing here is bitcrushed, stuttered or detuned: a glitch
/// reads as equipment failing, and this equipment is working perfectly well without you. Two
/// partials, a hard envelope and an optional chirp are the whole instrument.
/// </summary>
internal sealed class RDSignalToneVoice : RDVoice
{
    private float phase;
    private float phase3;

    private float frequency;
    private float chirpSemitones;
    private float chirpRemaining;
    private float chirpCoef;

    private float amp;
    private float peak;
    private float attackCoef;
    private float decayCoef;
    private bool attacking;

    // Third and fifth partials at full square-wave ratios. The first version used a weak third
    // only, which left a near-sine - and a near-sine with a soft attack is a bell, which is
    // exactly what the empty room must not contain. An odd-harmonic stack is a buzzer.
    private float edge;
    private float phase5;

    public override float CurrentLevel => amp;

    public override void Trigger(RDNoteEvent note)
    {
        SetPan(note.pan);

        frequency = Mathf.Max(60f, note.frequency);
        phase = 0f;
        phase3 = 0f;
        phase5 = 0f;

        peak = Mathf.Clamp(note.amplitude, 0f, 1f);
        amp = 0f;
        attacking = true;

        // 3 ms: fast enough to read as switched on, slow enough not to click. A true
        // instantaneous attack on a sine is a broadband transient and sounds like a fault.
        attackCoef = 1f - Mathf.Exp(-1f / (0.003f * sampleRate));
        decayCoef = DecayCoefficient(Mathf.Max(0.02f, note.decay));

        edge = Mathf.Lerp(0.30f, 0.62f, Mathf.Clamp01(note.brightness));

        // A quick sweep over about 50 ms - the chirp of something scanning or syncing.
        chirpSemitones = note.bend;
        chirpRemaining = chirpSemitones;
        chirpCoef = Mathf.Exp(-1f / (0.05f * sampleRate));
    }

    public override void Render(out float left, out float right)
    {
        if (attacking)
        {
            amp += (peak - amp) * attackCoef;
            if (amp >= peak * 0.98f) attacking = false;
        }
        else
        {
            amp *= decayCoef;
        }

        chirpRemaining *= chirpCoef;

        float semitones = chirpSemitones - chirpRemaining;
        float increment = TwoPi * frequency * Mathf.Pow(2f, semitones / 12f) / sampleRate;

        phase += increment;
        phase3 += increment * 3f;
        phase5 += increment * 5f;

        while (phase > TwoPi) phase -= TwoPi;
        while (phase3 > TwoPi) phase3 -= TwoPi;
        while (phase5 > TwoPi) phase5 -= TwoPi;

        if (!attacking && amp <= 0.00005f)
        {
            Active = false;
            left = 0f;
            right = 0f;
            return;
        }

        float value = (Mathf.Sin(phase)
                     + Mathf.Sin(phase3) * edge
                     + Mathf.Sin(phase5) * edge * 0.55f) * amp * 0.14f;

        left = value * panL;
        right = value * panR;
    }
}


/// <summary>
/// The room with nobody in it: a data centre.
///
/// This replaced a "bad signal" bed - band-limited hiss, a drifting carrier, dropouts - and the
/// spectrum is the whole difference. A lost radio signal lives at 1-7 kHz and reads as absence.
/// A machine room lives at 40-200 Hz and reads as something very large that does not need you:
/// fan fundamentals beating against each other, mains hum, air moving in ducts. You feel it in
/// the chest rather than the ears, and nothing about it is broken.
///
/// Not an RDVoice: it has no note and no envelope, it renders every sample for as long as the
/// piece is running, and its level comes from the main thread.
///
/// Kept out of the reverb on purpose. The fans are the building, not a sound in a room.
/// </summary>
internal sealed class RDSignalBed
{
    private readonly System.Random rng = new System.Random(5150);
    private readonly float sampleRate;

    // Written from the main thread, read on the audio thread. A float write is atomic on every
    // platform this runs on, and a frame of staleness inside a long fade is inaudible.
    private volatile float targetLevel;
    private volatile float targetUnrest;
    private volatile float targetBreath;

    private readonly float levelSlew;
    private readonly float breathSlew;

    private float level;
    private float unrest;
    private float breath;

    // How much the breath moves the room, as a fraction of its level. Larger than it looks: the
    // bed is mostly low frequency and the ear reads a swell down there as the room inhaling
    // rather than as a volume change.
    private const float BreathDepth = 0.22f;

    // Fan fundamentals, deliberately not in any harmonic relation: the slow beating between
    // them is the sound of a room with many machines in it rather than one.
    private static readonly float[] FanHz = { 43.5f, 57.3f, 71.1f, 94.7f, 118.3f };
    private readonly float[] fanPhase = new float[FanHz.Length];
    private readonly float[] fanDrift = new float[FanHz.Length];
    private readonly float[] fanDriftPhase = new float[FanHz.Length];

    // Mains at 50 Hz, because this is Bremen.
    private float humPhase;
    private float humPhase2;
    private float humPhase3;

    // Chamberlin state-variable filters: one resonant low for the rumble, one band for the whirr.
    private float lowL, bandL, lowR, bandR;
    private float whirrLowL, whirrBandL, whirrLowR, whirrBandR;

    private float airLpL, airLpR;

    private float whirrAmPhase;

    // Computation. Three slots of very short filtered tick, fired at a varying rate, so the room
    // sounds like work being done rather than like air being moved: disk seeks, relay clatter,
    // the fine-grained chatter of something calculating. Three is enough that they overlap at
    // high rates and stay distinct at low ones.
    private const int Ticks = 3;
    private readonly float[] tickAmp = new float[Ticks];
    private readonly float[] tickDecay = new float[Ticks];
    private readonly float[] tickLow = new float[Ticks];
    private readonly float[] tickBand = new float[Ticks];
    private readonly float[] tickF = new float[Ticks];
    private readonly float[] tickPan = new float[Ticks];

    // ---- the monitor -------------------------------------------------------------------
    //
    // A patient monitor, beeping over the machines. The empty room is not switched off, it is
    // unattended - and the one sound that says "still alive, nobody watching" in under a second
    // is this one.
    //
    // The clock lives HERE, on the audio thread, advanced per sample, and the picture reads the
    // envelope back off it. That direction matters: a frame of lag in the visual pump is
    // invisible, where a frame of jitter in the beep is immediately audible as an uneven pulse.
    // Driving it from Update would have put the jitter in the one place the ear is listening.
    private volatile float beatsPerSecond = 1f;
    private volatile float envelope;      // 0..1 cardiac shape, read by the surface
    private float beatPhase;
    private float sinceBeat;              // seconds, so the pulse SHAPE holds as the rate slows

    private int envelopeCountdown;
    private bool beepOn;
    private float beepT;
    private float beepPhase;
    private float beepHz;

    public RDSignalBed(float rate)
    {
        sampleRate = Mathf.Max(8000f, rate);

        // A long fade. Arriving and leaving a machine room is a crossfade, never a switch.
        levelSlew = 1f - Mathf.Exp(-1f / (2.5f * sampleRate));

        // Much faster, because this one is tracking a value that is already slow. Smoothing it
        // as heavily as the level would lag the picture by a second and break the alignment.
        breathSlew = 1f - Mathf.Exp(-1f / (0.08f * sampleRate));

        for (int i = 0; i < FanHz.Length; i++)
        {
            fanPhase[i] = (float)(rng.NextDouble() * TwoPi);
            fanDriftPhase[i] = (float)(rng.NextDouble() * TwoPi);
            fanDrift[i] = TwoPi * (0.013f + 0.021f * (float)rng.NextDouble()) / sampleRate;
        }
    }

    /// <summary>
    /// level: 0 silent, 1 full. unrest: how hard the room is working - lifts the whirr and the
    /// air without touching the rumble, so a busier room gets brighter rather than louder.
    /// </summary>
    public void SetLevel(float value, float unrestValue)
    {
        targetLevel = Mathf.Clamp01(value);
        targetUnrest = Mathf.Clamp01(unrestValue);
    }

    /// <summary>-1 to 1, from the same phase that breathes the surface.</summary>
    public void SetBreath(float value)
    {
        targetBreath = Mathf.Clamp(value, -1f, 1f);
    }

    /// <summary>Pulse rate for the monitor, in beats per minute. Slow it and the room settles.</summary>
    public void SetPulse(float beatsPerMinute)
    {
        beatsPerSecond = Mathf.Clamp(beatsPerMinute, 20f, 200f) / 60f;
    }

    /// <summary>The current cardiac envelope, 0 to 1. What the surface pumps on.</summary>
    public float PulseEnvelope => envelope;

    public bool Silent => level < 0.0004f && targetLevel < 0.0004f;

    public void Render(out float left, out float right)
    {
        level += (targetLevel - level) * levelSlew;
        unrest += (targetUnrest - unrest) * levelSlew;
        breath += (targetBreath - breath) * breathSlew;

        if (level < 0.0004f)
        {
            // Someone is here. No monitor, and the surface has nothing to pump on - the phase
            // resets so the first beep after they leave lands on a whole beat.
            envelope = 0f;
            beatPhase = 0f;
            sinceBeat = 0f;
            beepOn = false;

            left = 0f;
            right = 0f;
            return;
        }

        // ---- the monitor ---------------------------------------------------

        beatPhase += beatsPerSecond / sampleRate;
        sinceBeat += 1f / sampleRate;

        if (beatPhase >= 1f)
        {
            beatPhase -= 1f;
            sinceBeat = 0f;

            beepOn = true;
            beepT = 0f;
            beepPhase = 0f;

            // Just under A5, where monitors sit: high enough to cut through the fans, low
            // enough not to be an alarm. Alarms are a different piece.
            beepHz = 860f;
        }

        // Only the picture reads this, once a frame, so there is no point paying for two exp()
        // per sample to compute it. Every 64 samples is 1.3 ms of resolution against a 16 ms
        // frame - far finer than anything that can reach a screen.
        if (++envelopeCountdown >= 64)
        {
            envelopeCountdown = 0;
            envelope = RDAudioEngine.CardiacEnvelope(sinceBeat);
        }

        float beep = 0f;

        if (beepOn)
        {
            beepT += 1f / sampleRate;

            // 4 ms on so it does not click, 30 ms off so it does not ring. The glide down is
            // what makes it a "boop" rather than a "beep" - a flat tone reads as a test signal.
            float env = beepT < BeepAttack
                ? beepT / BeepAttack
                : Mathf.Exp(-(beepT - BeepAttack) / BeepDecay);

            beepPhase += TwoPi * beepHz / sampleRate;
            if (beepPhase > TwoPi) beepPhase -= TwoPi;

            beepHz -= 90f / sampleRate;

            beep = (Mathf.Sin(beepPhase)
                  + 0.18f * Mathf.Sin(beepPhase * 2f)
                  + 0.05f * Mathf.Sin(beepPhase * 3f)) * env;

            if (beepT > 0.26f) beepOn = false;
        }

        // ---- fans ---------------------------------------------------------

        float fans = 0f;

        for (int i = 0; i < FanHz.Length; i++)
        {
            fanDriftPhase[i] += fanDrift[i];
            if (fanDriftPhase[i] > TwoPi) fanDriftPhase[i] -= TwoPi;

            // Each fan breathes on its own slow cycle, so the beating never settles into a pattern.
            float amp = 0.6f + 0.4f * Mathf.Sin(fanDriftPhase[i]);

            fanPhase[i] += TwoPi * FanHz[i] / sampleRate;
            if (fanPhase[i] > TwoPi) fanPhase[i] -= TwoPi;

            fans += Mathf.Sin(fanPhase[i]) * amp / (1f + i * 0.55f);
        }

        fans *= 0.30f;

        // ---- mains hum, very faint ---------------------------------------

        humPhase += TwoPi * 50f / sampleRate;
        humPhase2 += TwoPi * 100f / sampleRate;
        humPhase3 += TwoPi * 150f / sampleRate;

        if (humPhase > TwoPi) humPhase -= TwoPi;
        if (humPhase2 > TwoPi) humPhase2 -= TwoPi;
        if (humPhase3 > TwoPi) humPhase3 -= TwoPi;

        float hum = (Mathf.Sin(humPhase) * 0.6f
                   + Mathf.Sin(humPhase2) * 0.25f
                   + Mathf.Sin(humPhase3) * 0.12f) * 0.05f;

        // ---- broadband, split into rumble / whirr / air -------------------

        float wl = (float)(rng.NextDouble() * 2.0 - 1.0);
        float wr = (float)(rng.NextDouble() * 2.0 - 1.0);

        // Resonant low around 80 Hz: the body of the room.
        float fLow = 2f * Mathf.Sin(Mathf.PI * 80f / sampleRate);
        lowL += fLow * bandL;
        bandL += fLow * (wl - lowL - 0.6f * bandL);
        lowR += fLow * bandR;
        bandR += fLow * (wr - lowR - 0.6f * bandR);

        // Band around 520 Hz: the whirr of blades, with a slow sweep so many fans are implied.
        whirrAmPhase += TwoPi * 0.21f / sampleRate;
        if (whirrAmPhase > TwoPi) whirrAmPhase -= TwoPi;

        float fWhirr = 2f * Mathf.Sin(Mathf.PI * 520f / sampleRate);
        whirrLowL += fWhirr * whirrBandL;
        whirrBandL += fWhirr * (wl - whirrLowL - 0.25f * whirrBandL);
        whirrLowR += fWhirr * whirrBandR;
        whirrBandR += fWhirr * (wr - whirrLowR - 0.25f * whirrBandR);

        float whirrAm = 0.65f + 0.35f * Mathf.Sin(whirrAmPhase);

        // Air in the ducts: present but well under the rumble. The old bed lived up here.
        airLpL += (wl - airLpL) * 0.35f;
        airLpR += (wr - airLpR) * 0.35f;

        // ---- computation ---------------------------------------------------

        // Rate rises with unrest: a room thinking harder ticks faster. Irregular by construction
        // - a Poisson trigger rather than a clock - because anything periodic reads as a metronome
        // and a machine working does not keep time.
        float ticksPerSecond = Mathf.Lerp(7f, 48f, unrest);

        if (rng.NextDouble() < ticksPerSecond / sampleRate)
        {
            for (int i = 0; i < Ticks; i++)
            {
                if (tickAmp[i] > 0.004f) continue;

                tickAmp[i] = 0.5f + 0.5f * (float)rng.NextDouble();

                // 1.4 to 5.5 kHz: the register of a mechanism, above the fans and below hiss.
                float hz = 1400f + 4100f * (float)rng.NextDouble();
                tickF[i] = 2f * Mathf.Sin(Mathf.PI * Mathf.Min(hz, sampleRate * 0.45f) / sampleRate);

                // 1.5 to 6 ms. Longer than that stops being a tick and starts being a tone.
                float seconds = 0.0015f + 0.0045f * (float)rng.NextDouble();
                tickDecay[i] = Mathf.Exp(-6.9078f / (seconds * sampleRate));

                tickPan[i] = (float)(rng.NextDouble() * 2.0 - 1.0);
                tickLow[i] = 0f;
                tickBand[i] = 0f;

                break;
            }
        }

        float tickL = 0f;
        float tickR = 0f;

        for (int i = 0; i < Ticks; i++)
        {
            if (tickAmp[i] <= 0.004f) continue;

            float excite = (float)(rng.NextDouble() * 2.0 - 1.0) * tickAmp[i];

            tickLow[i] += tickF[i] * tickBand[i];
            tickBand[i] += tickF[i] * (excite - tickLow[i] - 0.22f * tickBand[i]);

            float v = tickBand[i];
            float p = tickPan[i];

            tickL += v * (1f - Mathf.Max(0f, p)) * 0.5f;
            tickR += v * (1f + Mathf.Min(0f, p)) * 0.5f;

            tickAmp[i] *= tickDecay[i];
        }

        // ---- mix ------------------------------------------------------------

        float airGain = 0.035f + 0.045f * unrest;
        float whirrGain = (0.11f + 0.09f * unrest) * whirrAm;
        float tickGain = 0.13f;

        float bodyL = lowL * 2.2f + fans + hum;
        float bodyR = lowR * 2.2f + fans + hum;

        float g = level * 0.42f * (1f + breath * BreathDepth);

        // Centre, and loud enough to sit on top of the machines rather than inside them. The
        // beep is not part of the room's body, it is a thing in the room.
        float monitor = beep * 0.34f;

        left = (bodyL + whirrLowL * whirrGain + airLpL * airGain + tickL * tickGain + monitor) * g;
        right = (bodyR + whirrLowR * whirrGain + airLpR * airGain + tickR * tickGain + monitor) * g;
    }

    private const float BeepAttack = 0.004f;
    private const float BeepDecay = 0.030f;
    private const float TwoPi = 6.28318530718f;
}

// ===========================================================================================
//  Room
// ===========================================================================================

/// <summary>
/// Schroeder reverb: four parallel comb filters into two series allpasses. Cheap, and the right
/// era of algorithm for this material. The left and right comb lengths are mutually prime so the
/// tail decorrelates instead of sounding like one mono blur.
/// </summary>
internal sealed class RDReverb
{
    private static readonly int[] CombLeft = { 1557, 1617, 1491, 1422 };
    private static readonly int[] CombRight = { 1580, 1640, 1514, 1445 };
    private static readonly int[] AllpassLengths = { 225, 556 };

    private readonly float[][] combBufL;
    private readonly float[][] combBufR;
    private readonly int[] combIdxL;
    private readonly int[] combIdxR;
    private readonly float[] combStoreL;
    private readonly float[] combStoreR;

    private readonly float[][] apBufL;
    private readonly float[][] apBufR;
    private readonly int[] apIdxL;
    private readonly int[] apIdxR;

    private float feedback = 0.82f;
    private float damping = 0.35f;

    public RDReverb(float sampleRate)
    {
        // The classic constants assume 44.1 kHz; scale so the room does not change size with the
        // output device.
        float scale = sampleRate / 44100f;

        combBufL = new float[CombLeft.Length][];
        combBufR = new float[CombRight.Length][];
        combIdxL = new int[CombLeft.Length];
        combIdxR = new int[CombRight.Length];
        combStoreL = new float[CombLeft.Length];
        combStoreR = new float[CombRight.Length];

        for (int i = 0; i < CombLeft.Length; i++)
        {
            combBufL[i] = new float[Mathf.Max(8, Mathf.RoundToInt(CombLeft[i] * scale))];
            combBufR[i] = new float[Mathf.Max(8, Mathf.RoundToInt(CombRight[i] * scale))];
        }

        apBufL = new float[AllpassLengths.Length][];
        apBufR = new float[AllpassLengths.Length][];
        apIdxL = new int[AllpassLengths.Length];
        apIdxR = new int[AllpassLengths.Length];

        for (int i = 0; i < AllpassLengths.Length; i++)
        {
            apBufL[i] = new float[Mathf.Max(8, Mathf.RoundToInt(AllpassLengths[i] * scale))];
            apBufR[i] = new float[Mathf.Max(8, Mathf.RoundToInt(AllpassLengths[i] * scale) + 3)];
        }
    }

    public void SetParameters(float feedbackAmount, float dampingAmount)
    {
        feedback = Mathf.Clamp(feedbackAmount, 0f, 0.99f);
        damping = Mathf.Clamp(dampingAmount, 0f, 0.95f);
    }

    public void Process(float inL, float inR, out float outL, out float outR)
    {
        float input = (inL + inR) * 0.25f;

        float accL = 0f;
        float accR = 0f;

        for (int i = 0; i < combBufL.Length; i++)
        {
            accL += ProcessComb(combBufL[i], ref combIdxL[i], ref combStoreL[i], input);
            accR += ProcessComb(combBufR[i], ref combIdxR[i], ref combStoreR[i], input);
        }

        for (int i = 0; i < apBufL.Length; i++)
        {
            accL = ProcessAllpass(apBufL[i], ref apIdxL[i], accL);
            accR = ProcessAllpass(apBufR[i], ref apIdxR[i], accR);
        }

        outL = accL;
        outR = accR;
    }

    private float ProcessComb(float[] buffer, ref int index, ref float store, float input)
    {
        float output = buffer[index];

        // One-pole lowpass inside the loop: the tail loses its brightness with each pass,
        // like sound in a stone hall.
        store = output * (1f - damping) + store * damping;
        buffer[index] = input + store * feedback;

        index++;
        if (index >= buffer.Length) index = 0;

        return output;
    }

    private float ProcessAllpass(float[] buffer, ref int index, float input)
    {
        float buffered = buffer[index];
        float output = -input + buffered;

        buffer[index] = input + buffered * 0.5f;

        index++;
        if (index >= buffer.Length) index = 0;

        return output;
    }
}
